fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only need to iterate over parent indices 0..n/2 (floor division).
    // Any index i in this range has at least a left child at 2*i+1.
    for i in 0..(n / 2) {
        let parent = a[i];
        let left = 2 * i + 1;
        // Check left child
        if left < n && parent > a[left] {
            return false;
        }
        let right = 2 * i + 2;
        // Check right child
        if right < n && parent > a[right] {
            return false;
        }
    }
    true
}

